&lt;span id=&#34;cb7-23&#34;&gt;&lt;a href=&#34;#cb7-23&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;                &lt;span class=&#34;op&#34;&gt;++&lt;/span&gt;j&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
